(7534716, 1205009, 185757, '<td valign="top">Great idea, and I think you really nailed the exact moment for maximum effect. Top 3 pick for me.</td>', 'Great idea, and I think you really nailed the exact moment for maximum effect. Top 3 pick for me.', '2017-09-12 19:06:00.000000', NULL, 1),
(7534717, 1205108, 185757, '<td valign="top">I think the crop here for your composition is perfect, making it seem very surreal. Top 3 pick for me.</td>', 'I think the crop here for your composition is perfect, making it seem very surreal. Top 3 pick for me.', '2017-09-12 19:07:56.000000', NULL, 1),
